create table if not exists public.letmytrip_chat_leads(id uuid primary key,name text not null,mobile text not null,source text,page_url text,status text not null default 'new',assigned_to text,created_at timestamptz not null default now());create table if not exists public.letmytrip_chat_messages(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.letmytrip_chat_leads(id) on delete cascade,sender text not null check(sender in ('customer','bot','staff')),message text not null,created_at timestamptz not null default now());create index if not exists lmt_chat_leads_created_idx on public.letmytrip_chat_leads(created_at desc);create index if not exists lmt_chat_messages_conv_idx on public.letmytrip_chat_messages(conversation_id,created_at);alter table public.letmytrip_chat_leads enable row level security;alter table public.letmytrip_chat_messages enable row level security;